arguments.command:
curl -s -H "Authorization: Bearer <TOKEN>" "https://www.googleapis.com/calendar/v3/calendars/primary/events?maxResults=250&singleEvents=true" | python3 -c "
import json,sys
d=json.load(sys.stdin)
items=d.get('items',[])
print('total:',len(items))
for e in items:
    att={a.get('displayName'):a.get('responseStatus') for a in e.get('attendees',[])}
    if any(v=='declined' for v in att.values()):
        print('DECLINED:', e['id'], e.get('summary'), e['start'].get('dateTime'), e.get('recurrence'), att)
"

